/* C API of the Rust port of `sensout.c`, generated by rust-anything. */
#ifndef SENSOUT_RS_H
#define SENSOUT_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

double CompOutput(int which, double m, double t2, double w2, double t1, double w1);
double ZoneOutput(int which, double m, double te, double we, double tz, double wz);
double ZoneSensOutput(double m, double te, double tz, double wz);

/* The same functions under `rust_anything_` names, for shadow runs. */
double rust_anything_CompOutput(int which, double m, double t2, double w2, double t1, double w1);
double rust_anything_ZoneOutput(int which, double m, double te, double we, double tz, double wz);
double rust_anything_ZoneSensOutput(double m, double te, double tz, double wz);

#endif /* SENSOUT_RS_H */
